from collections import deque
def shapes(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                mine=min(ys); minx=min(xs)
                norm=tuple(sorted((y-mine,x-minx) for y,x in cells))
                out.append({'col':col,'norm':norm,'cells':cells,'y':mine,'x':minx})
    return out

def normkey(s):
    # normalize shape by trimming to bounding box
    ys=[c[0] for c in s['cells']]; xs=[c[1] for c in s['cells']]
    y0,x0=min(ys),min(xs)
    return tuple(sorted((y-y0,x-x0) for y,x in s['cells']))

