import json
def transform(g):
    h,w=len(g),len(g[0]); seen=set(); shapes=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                y0,x0=min(ys),min(xs)
                shapes.append({'col':col,'key':tuple(sorted((y-y0,x-x0) for y,x in cells)),'cells':cells})
    out=[row[:] for row in g]
    for a in range(len(shapes)):
        for b in range(len(shapes)):
            s,t=shapes[a],shapes[b]
            if a!=b and s['key']==t['key'] and s['col']!=t['col'] and s['col']==1:
                for y,x in s['cells']: out[y][x]=t['col']
    return out
